<script lang="ts">
  import Modal from '../Modal.svelte';
  import Button from '../Button.svelte';
  import Field from '../Field.svelte';
  import type { Database } from '../../databaseTypes';
  interface Props {
    open: boolean;
    mode: 'create' | 'rename';
    database?: Database | null;
    busy?: boolean;
    error?: string;
    onsubmit: (name: string) => void;
    onclose: () => void;
  }
  let { open, mode, database = null, busy=false, error, onsubmit, onclose }: Props = $props();
  let name = $state('');
  let validation = $state('');
  $effect(() => { if (open) { name = mode === 'rename' ? (database?.name ?? '') : ''; validation=''; } });
  const title = $derived(mode === 'rename' ? `Rename ${database?.name ?? 'database'}` : 'Create database');
  function submit() {
    const value = name.trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(value)) { validation = 'Use letters, numbers and underscores; start with a letter or underscore.'; return; }
    if (value.length > 63) {...}
    if (mode === 'rename' && value === database?.name) { validation = 'Enter a different name.'; return; }
    onsubmit(value);
  }
</script>
<Modal open={open} title={title} description=... onclose={onclose}>
  <Field id="database-name" label="Database name" error={validation || error} hint="...">
    <input id="database-name" class="input mono" bind:value={name} data-autofocus onkeydown={(e)=> e.key==='Enter' && submit()} />
  </Field>
  {#snippet footer()}
    <Button variant="ghost" onclick={onclose} disabled={busy}>Cancel</Button>
    <Button variant="primary" onclick={submit} loading={busy}>{mode==='rename'?'Rename database':'Create database'}</Button>
  {/snippet}
</Modal>
