import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { fireEvent, render, screen, waitFor, within } from '@testing-library/svelte';
import UsersTab from './UsersTab.svelte';
import * as db from '../../databaseApi';
import type { Database, DatabaseUser } from '../../databaseTypes';
import type { ServiceView } from '../../types';

vi.mock('../../databaseApi', async (importOriginal) => {
  const actual = await importOriginal<typeof import('../../databaseApi')>();
  return {
    ...actual,
    createServiceUser: vi.fn(),
    updateServiceUser: vi.fn(),
    deleteServiceUser: vi.fn(),
    setServiceUserPassword: vi.fn(),
    revealServiceUserPassword: vi.fn(),
  };
});

const MYSQL_SERVICE: ServiceView = {
  id: 'mysql',
  display_name: 'MySQL 8.4',
  group: 'mysql-family',
  state: 'active',
  active: true,
  installed: true,
  health: 'healthy',
  container_id: 'a1b2c3d4e5f6',
  image: 'mysql:8.4.13',
  ports: [{ host: 3306, container: 3306, protocol: 'tcp', loopback: true }],
  config_path: '/data/devstack/services/mysql/config',
  data_path: '/data/devstack/services/mysql/data',
};

const POSTGRES_SERVICE: ServiceView = {
  ...MYSQL_SERVICE,
  id: 'postgresql',
  display_name: 'PostgreSQL 18',
  group: 'standalone',
  image: 'postgres:18.1',
  ports: [{ host: 5432, container: 5432, protocol: 'tcp', loopback: true }],
};

const REDIS_SERVICE: ServiceView = {
  ...MYSQL_SERVICE,
  id: 'redis',
  display_name: 'Redis 8.8',
  group: 'standalone',
  image: 'redis:8.8.3',
  ports: [{ host: 6379, container: 6379, protocol: 'tcp', loopback: true }],
};

const MYSQL_DATABASES: Database[] = [
  {
    name: 'app',
    service_id: 'mysql',
    engine: 'mysql',
    size_bytes: 13_000_000,
    table_count: 12,
    linked_sites: [],
    managed: true,
  },
  {
    name: 'blog',
    service_id: 'mysql',
    engine: 'mysql',
    size_bytes: 4_200_000,
    table_count: 7,
    linked_sites: [],
    managed: true,
  },
];

const POSTGRES_DATABASES: Database[] = [
  {
    name: 'app',
    service_id: 'postgresql',
    engine: 'postgres',
    size_bytes: 8_000_000,
    table_count: 9,
    linked_sites: [],
    managed: true,
  },
];

const MYSQL_USERS: DatabaseUser[] = [
  {
    id: 'usr_app',
    service_id: 'mysql',
    engine: 'mysql',
    username: 'app',
    host: '%',
    enabled: true,
    managed: true,
    password_managed: true,
    grants: [{ database: 'app', preset: 'read_write_schema' }],
    linked_sites: [],
  },
  {
    id: 'usr_ext',
    service_id: 'mysql',
    engine: 'mysql',
    username: 'external',
    host: '%',
    enabled: true,
    managed: false,
    password_managed: false,
    grants: [],
    linked_sites: [],
  },
];

const LINKED_USER: DatabaseUser = {
  ...MYSQL_USERS[0],
  linked_sites: [{ id: 'site_blog', name: 'blog' }],
};

const POSTGRES_USER: DatabaseUser = {
  id: 'usr_pg',
  service_id: 'postgresql',
  engine: 'postgres',
  username: 'app',
  enabled: true,
  managed: true,
  password_managed: true,
  grants: [{ database: 'app', preset: 'read_write_schema' }],
  linked_sites: [],
};

const REDIS_USERS: DatabaseUser[] = [
  {
    id: 'usr_cache',
    service_id: 'redis',
    engine: 'redis',
    username: 'cache',
    enabled: true,
    managed: true,
    password_managed: true,
    access_level: 'read-only',
    grants: [],
    linked_sites: [],
  },
  {
    id: 'usr_default',
    service_id: 'redis',
    engine: 'redis',
    username: 'default',
    enabled: true,
    managed: false,
    password_managed: true,
    access_level: 'full',
    grants: [],
    linked_sites: [],
  },
];

beforeEach(() => {
  vi.mocked(db.revealServiceUserPassword).mockResolvedValue({ value: 's3cret' });
  vi.mocked(db.setServiceUserPassword).mockResolvedValue({ value: 'n3w-secret' });
  vi.mocked(db.deleteServiceUser).mockResolvedValue(undefined);
  vi.mocked(db.createServiceUser).mockResolvedValue({
    id: 'usr_api',
    service_id: 'mysql',
    engine: 'mysql',
    username: 'api',
    host: '%',
    enabled: true,
    managed: true,
    password_managed: true,
    grants: [{ database: 'app', preset: 'read_write_schema' }],
    linked_sites: [],
  });
  vi.mocked(db.updateServiceUser).mockResolvedValue(MYSQL_USERS[0]);
});

afterEach(() => {
  vi.clearAllMocks();
});

describe('UsersTab', () => {
  it('shows managed and external users with grants', () => {
    render(UsersTab, {
      props: {
        service: MYSQL_SERVICE,
        users: MYSQL_USERS,
        databases: MYSQL_DATABASES,
        onRefresh: vi.fn(),
      },
    });

    expect(screen.getByText('app')).toBeTruthy();
    expect(screen.getByText('external')).toBeTruthy();
    expect(screen.getByText('read/write + schema on app')).toBeTruthy();
    expect(screen.getByText('Managed')).toBeTruthy();
    expect(screen.getByText('External')).toBeTruthy();
  });

  it('reveals a password only after the audited call', async () => {
    render(UsersTab, {
      props: {
        service: MYSQL_SERVICE,
        users: MYSQL_USERS,
        databases: MYSQL_DATABASES,
        onRefresh: vi.fn(),
      },
    });

    expect(screen.queryByText('s3cret')).toBeNull();

    await fireEvent.click(screen.getByRole('button', { name: /reveal password for app/i }));

    expect(await screen.findByText('s3cret')).toBeTruthy();
    expect(db.revealServiceUserPassword).toHaveBeenCalledWith('mysql', 'usr_app');
  });

  it('blocks deleting a user linked to a site', () => {
    render(UsersTab, {
      props: {
        service: MYSQL_SERVICE,
        users: [LINKED_USER],
        databases: MYSQL_DATABASES,
        onRefresh: vi.fn(),
      },
    });

    const remove = screen.getByRole('button', { name: /delete app/i }) as HTMLButtonElement;
    expect(remove.disabled).toBe(true);
    expect(screen.getByText(/unlink sites/i)).toBeTruthy();
  });

  it('deletes an unlinked user after the typed confirmation', async () => {
    render(UsersTab, {
      props: {
        service: MYSQL_SERVICE,
        users: MYSQL_USERS,
        databases: MYSQL_DATABASES,
        onRefresh: vi.fn(),
      },
    });

    await fireEvent.click(screen.getByRole('button', { name: /delete app/i }));
    const dialog = await screen.findByRole('dialog');
    await fireEvent.input(within(dialog).getByLabelText(/type .app. to confirm/i), {
      target: { value: 'app' },
    });
    await fireEvent.click(within(dialog).getByRole('button', { name: 'Delete user' }));

    await waitFor(() =>
      expect(db.deleteServiceUser).toHaveBeenCalledWith('mysql', 'usr_app', {
        confirm: 'app',
        reassign_owned: false,
      }),
    );
  });

  it('offers PostgreSQL owned-object reassignment before deleting a role', async () => {
    render(UsersTab, {
      props: {
        service: POSTGRES_SERVICE,
        users: [POSTGRES_USER],
        databases: POSTGRES_DATABASES,
        onRefresh: vi.fn(),
      },
    });

    await fireEvent.click(screen.getByRole('button', { name: /delete app/i }));
    const dialog = await screen.findByRole('dialog');
    await fireEvent.click(
      within(dialog).getByLabelText('Reassign owned objects to devstack admin'),
    );
    await fireEvent.input(within(dialog).getByLabelText(/type .app. to confirm/i), {
      target: { value: 'app' },
    });
    await fireEvent.click(within(dialog).getByRole('button', { name: 'Delete user' }));

    await waitFor(() =>
      expect(db.deleteServiceUser).toHaveBeenCalledWith('postgresql', 'usr_pg', {
        confirm: 'app',
        reassign_owned: true,
      }),
    );
  });

  it('creates a managed user with a database-scoped grant', async () => {
    render(UsersTab, {
      props: {
        service: MYSQL_SERVICE,
        users: MYSQL_USERS,
        databases: MYSQL_DATABASES,
        onRefresh: vi.fn(),
      },
    });

    await fireEvent.click(screen.getByRole('button', { name: 'Create user' }));
    const dialog = await screen.findByRole('dialog');
    await fireEvent.input(within(dialog).getByLabelText('Username'), {
      target: { value: 'api' },
    });
    await fireEvent.click(within(dialog).getByRole('button', { name: 'Create user' }));

    await waitFor(() =>
      expect(db.createServiceUser).toHaveBeenCalledWith('mysql', {
        username: 'api',
        host: '%',
        grants: [{ database: 'app', preset: 'read_write_schema' }],
      }),
    );
  });

  it('hides host and grants for Redis and shows the access level', () => {
    render(UsersTab, {
      props: {
        service: REDIS_SERVICE,
        users: REDIS_USERS,
        databases: [],
        onRefresh: vi.fn(),
      },
    });

    expect(screen.getByText('cache')).toBeTruthy();
    expect(screen.getByText('read-only')).toBeTruthy();
    expect(screen.queryByText('Grants')).toBeNull();
    expect(screen.queryByText('Host')).toBeNull();
    expect(screen.getByText(/full means all data commands/i)).toBeTruthy();
  });
});

content.text:
All 7 fail as expected. Now implement.

First `userGrants.ts`.

Grant presets:
- read_only: "Read-only"
- read_write: "Read/write"
- read_write_schema: "Read/write + schema"
- admin: "Admin (database-scoped)"
- custom: "Custom"

Summary labels lowercase per test: "read/write + schema on app". Use summary labels lowercase:
- read_only: 'read-only'
- read_write: 'read/write'
- read_write_schema: 'read/write + schema'
- admin: 'admin'
- custom: 'custom'

Custom privileges list. Use uppercase privilege names.

Protected users per engine.

Redis access description:
`full` ÔåÆ "Full data access (admin and dangerous commands excluded)"
`read-only` ÔåÆ "Read-only data access"

Now `GrantEditor.svelte`. Keep controlled.

One concern: when `grants` prop changes externally (edit dialog open), the rows should update. We render directly from prop, no local copy. On change, we emit a new array. Parent (UserFormDialog) stores in local state and passes back. Good.

`addGrant`: choose first database not already used; if none, return.
`removeGrant(index)`: filter.
`updateDatabase(index, name)`: map.
`updatePreset(index, preset)`: map, reset privileges for non-custom.
`togglePrivilege(index, privilege)`: map.

Svelte each with index and key: `{#each grants as grant, index (index)}` ÔÇö using index as key is okay for this small editor, but changing order could confuse; no reorder.

Labels: `Grant ${index + 1} database`, `Grant ${index + 1} preset`. The first row labels are "Grant 1 database". Test create doesn't interact with them, relying on defaults.

`UserFormDialog.svelte`:

```svelte
<script lang="ts">
  import { DatabaseEngine, DatabaseUser, Database, DatabaseGrant } from ...
  import { CUSTOM_PRIVILEGES } from './userGrants';
  import GrantEditor from './GrantEditor.svelte';
  ...
  export interface UserFormValue {...} // can't export from instance script in Svelte 5? You can use <script module>.
```

I'll define the `UserFormValue` type in `userGrants.ts` to avoid module script complexities:
```ts
export interface UserFormValue {
  username: string;
  host: string;
  enabled: boolean;
  accessLevel: string;
  grants: DatabaseGrant[];
}
```

UserFormDialog uses `UserFormValue`.

Local state:
```ts
let username = $state('');
let host = $state('%');
let enabled = $state(true);
let accessLevel = $state('read-only');
let grants = $state<DatabaseGrant[]>([]);
let validation = $state<Record<string,string>>({});
```
Effect on open:
```ts
$effect(() => {
  if (!open) return;
  username = mode === 'edit' ? (user?.username ?? '') : '';
  host = user?.host || (engine === 'postgres' || engine === 'redis' ? '' : '%');
  enabled = user?.enabled ?? true;
  accessLevel = user?.access_level === 'full' ? 'full' : 'read-only';
  grants = mode === 'edit'
    ? (user?.grants ?? []).map(g => ({...g, privileges: g.privileges ? [...g.privileges] : undefined}))
    : databases.length > 0 && engine !== 'redis'
      ? [{ database: databases[0].name, preset: 'read_write_schema' }]
      : [];
  validation = {};
});
```
Careful: the effect reads `databases` and `user`; if parent rerenders with same props no issue. When `open` changes to true, runs. When open stays true and grants change internally? The effect doesn't read `grants`, so not re-run. Good.

But `$effect` writing to `grants` and reading `databases` (prop) ÔÇö fine.

Submit:
```ts
function submit() {
  const name = username.trim();
  const errors: Record<string,string> = {};
  if (!name) errors.username = 'Username is required.';
  else if (/\s/.test(name)) errors.username = 'Usernames cannot contain spaces.';
  else if (!/^[A-Za-z0-9_.-]+$/.test(name)) errors.username = 'Use letters, numbers, dots, dashes or underscores.';
  if ((engine === 'mysql' || engine === 'mariadb') && !host.trim()) errors.host = 'Host scope is required.';
  if (Object.keys(errors).length) { validation = errors; return; }
  validation = {};
  onsubmit({ username: name, host: host.trim(), enabled, accessLevel, grants: engine === 'redis' ? [] : grants });
}
```
The test enters username 'api', host default '%', default grants app/read_write_schema. The parent sends create body:
```ts
{
  username: value.username,
  host: value.host || undefined,
  grants: value.grants,
}
```
Assertion expects `host:'%'` and grants. Good.

Markup:
```svelte
<Modal open={open} title={...} description=... onclose={onclose} size="md">
  <div class="form-grid">
    <Field id="user-username" label="Username" error={validation.username} required>
      <input id="user-username" class="input mono" bind:value={username} data-autofocus ... />
    </Field>
    {#if engine === 'mysql' || engine === 'mariadb'}
      <Field id="user-host" label="Host" error={validation.host} hint="Use % for devstack-managed users.">
        <input id="user-host" class="input mono" bind:value={host} />
      </Field>
    {/if}
  </div>
  {#if engine === 'redis'}
    <Field id="user-access" label="Access level">
      <select id="user-access" class="input" bind:value={accessLevel}>
        <option value="read-only">Read-only</option>
        <option value="full">Full data access (admin and dangerous commands excluded)</option>
      </select>
    </Field>
  {:else}
    <GrantEditor {databases} {grants} {engine} onchange={(next)=> (grants=next)} />
  {/if}
  {#if mode === 'edit'}
    <Toggle bind:checked={enabled} label="Enabled" description="Disabled users keep their grants but cannot connect." />
  {/if}
  {#if error}<p class="form-error" role="alert">{error}</p>{/if}
  {#snippet footer()}
    <Button variant="ghost" onclick={onclose} disabled={busy}>Cancel</Button>
    <Button variant="primary" onclick={submit} loading={busy}>{mode === 'edit' ? 'Save changes' : 'Create user'}</Button>
  {/snippet}
</Modal>
```

Test: `within(dialog).getByLabelText('Username')` works. `getByRole('button',{name:'Create user'})` inside dialog. Header button also "Create user" but within dialog only footer.

Now UsersTab implementation. Let me write it fully.

Imports: Card, Button, Badge, ConfirmDialog, EmptyState, ErrorBanner, Modal, SecretField, UserFormDialog, userGrants helpers, copyText, describeError.

Props: `{ service, users, databases, loading?, selectedUserId?, onRefresh }`.

Engine derived: from users[0]?.engine ?? service id mapping.

State:
```ts
let formOpen = $state(false);
let formMode = $state<'create'|'edit'>('create');
let editTarget = $state<DatabaseUser|null>(null);
let formBusy = $state(false);
let formError = $state('');
let deleteTarget = $state<DatabaseUser|null>(null);
let deleting = $state(false);
let deleteError = $state<DescribedError|null>(null);
let reassignOwned = $state(false);
let unlinkTarget = $state<DatabaseUser|null>(null);
let revealed = $state<Record<string,string>>({});
let revealing = $state<Record<string,boolean>>({});
let revealErrors = $state<Record<string,string>>({});
let secretDialog = $state<{user: DatabaseUser; value: string; revealed: boolean} | null>(null);
let secretBusy = $state<string|null>(null);
let actionError = $state<DescribedError|null>(null);
```

`isRedis = engine === 'redis'`.

Effect to clear revealed when users change:
```ts
$effect(() => {
  users;
  revealed = {};
  revealErrors = {};
});
```
This might clear immediately after reveal if the parent updates users due to something else. Fine.

But wait: in the reveal test, `users` prop is a stable array; the effect runs once on mount, sets revealed={}. Then click reveal sets revealed. No further effect run. Good.

`openCreate`, `openEdit`, `submitForm(value)`.

Create body:
```ts
const body: CreateDatabaseUserRequest = { username: value.username };
if (engine === 'mysql' || engine === 'mariadb') body.host = value.host;
if (engine === 'redis') body.access_level = value.accessLevel;
else body.grants = value.grants;
await db.createServiceUser(service.id, body);
```
Test expects exactly `{username, host, grants}`. Since engine mysql, body has username, host, grants. No access_level key. Good.

Edit body:
```ts
const body: UpdateDatabaseUserRequest = { enabled: value.enabled };
if (engine === 'redis') body.access_level = value.accessLevel;
else body.grants = value.grants;
```

`resetPassword(user)`:
```ts
secretBusy = user.id;
try {
  const secret = await db.setServiceUserPassword(service.id, user.id);
  secretDialog = { user, value: secret.value, revealed: true };
  addToast({kind:'success', title:`Password reset for ${user.username}`, message:'Copy the new password now; it is stored by the platform.'});
  onRefresh();
} catch (caught) { actionError = describeError(caught); } finally { secretBusy = null; }
```
For metadata-only "Set password", same.

`reveal(user)`:
```ts
revealing = {...revealing, [user.id]: true};
delete revealErrors[user.id]? Use new object.
try { const secret = await db.revealServiceUserPassword(service.id, user.id); revealed = {...revealed, [user.id]: secret.value}; }
catch (caught) { revealErrors = {...revealErrors, [user.id]: describeError(caught).message}; }
finally { revealing = {...revealing, [user.id]: false}; }
```
`hide`: `const next={...revealed}; delete next[user.id]; revealed=next;`
`copySecret(user)`: copyText(revealed[user.id]) then toast.

`confirmDelete`:
```ts
await db.deleteServiceUser(service.id, target.id, { confirm: target.username, reassign_owned: engine === 'postgres' ? reassignOwned : false });
```
Test expects reassign_owned false for mysql. Good. For postgres true after checking. 

`openDelete`: reset reassignOwned=false, deleteError=null, deleteTarget=user.

`unlink`: `unlinkTarget = user`.

`linked(user) = (user.linked_sites?.length ?? 0) > 0`.
`protectedUser(user) = isProtectedUsername(engine, user.username)`.

Delete button disabled when !active || linked || protected. Title explains.

For protected default Redis user, show Badge "Protected" maybe.

Markup SQL table and Redis table. To reduce duplication, use a single table with conditional columns:
```svelte
{#if isRedis}
  table with columns User, State, Access, Password, Actions
{:else}
  table with columns User, Host, State, Password, Grants, Linked sites, Actions
{/if}
```
Duplicated row markup is long. Could use a shared row snippet? Svelte snippets with parameters:
```svelte
{#snippet userRow(user: DatabaseUser)}
  <tr>...</tr>
{/snippet}
```
