import { describe, expect, it } from 'vitest';
import { isRefreshEvent } from './events';

describe('isRefreshEvent', () => {
  it.each([
    'site.updated',
    'runtime.installed',
    'doctor.updated',
    'trust.updated',
    'service.activated',
    'database.created',
    'database.job.updated',
    'database.backup.restored',
    'redis.user.created',
    'redis.password.changed',
  ])('refreshes for %s', (type) => {
    expect(isRefreshEvent(type)).toBe(true);
  });

  it.each(['log.line', 'terminal.output', 'database', 'redisson.updated'])(
    'ignores %s',
    (type) => {
      expect(isRefreshEvent(type)).toBe(false);
    },
  );
});

/**
 * Event types that invalidate dashboard inventory. Database and Redis
 * mutations refresh the service/site views through the same signal as the
 * existing site/service events.
 */
export function isRefreshEvent(type: string): boolean {
  return /^(site|runtime|doctor|trust|service|database|redis)\./.test(type);
}

