Let's implement.

UsersTab import:
`import * as api from '../../api';`
type add DatabaseSiteRef.
State:
```ts
let restartPrompt = $state<{ label: string; sites: DatabaseSiteRef[] } | null>(null);
let restartingSite = $state<string | null>(null);
```
Helper:
```ts
function promptRestart(label: string, sites: DatabaseSiteRef[] | undefined) {
  if (!sites?.length) return;
  restartPrompt = { label, sites: [...sites] };
}
async function restartLinkedSite(site: DatabaseSiteRef) {
  if (restartingSite) return;
  restartingSite = site.id;
  try {
    await api.restartSite(site.id);
    addToast({kind:'success', title:`${site.name} restarted`, message:'The site now uses the updated database credentials.'});
    if (restartPrompt) {
      const remaining = restartPrompt.sites.filter(s => s.id !== site.id);
      restartPrompt = remaining.length ? { ...restartPrompt, sites: remaining } : null;
    }
  } catch (caught) { actionError = describeError(caught); }
  finally { restartingSite = null; }
}
```
